  insert into public.strategy_plan (key, value, updated_by) values ('mission', '"Welfare Avenue is a youth-powered non-profit dedicated to fighting food insecurity and poverty through direct community action. We deliver meals and essential support directly to people where they are."'::jsonb, 'wave205 migration');
  insert into public.strategy_plan (key, value, updated_by) values ('mission_note', '"The mission adopted in July 2026. Every goal serves it."'::jsonb, 'wave205 migration');
  insert into public.strategy_plan (key, value, updated_by) values ('window', '"Five goals for FY27 to FY29 (Oct 1, 2026 to Sep 30, 2029), with a gated view to FY31."'::jsonb, 'wave205 migration');
  insert into public.strategy_plan (key, value, updated_by) values ('why_reset', '"At the July 2026 mid-year check, program impact was behind and the financial cushion had not started. This plan keeps the ambition and adds what was missing: a baseline, owners, yearly milestones, and a named engine (donor team, flagship events, grants, paid roles) behind every number. Targets start from measured baselines. All targets are proposals for board approval."'::jsonb, 'wave205 migration');
  insert into public.strategy_plan (key, value, updated_by) values ('long_range', '"Leadership''s long-range target (Oct 2025) is $5 million in revenue and 1 million meals within 10 years, in five cities. This plan is the first five years toward it."'::jsonb, 'wave205 migration');
  insert into public.strategy_plan (key, value, updated_by) values ('approval', '{"meeting": "2026-10-19", "label": "Draft for board approval (19 Oct 2026)", "final_draft": "2026-10-10"}'::jsonb, 'wave205 migration');
  insert into public.strategy_plan (key, value, updated_by) values ('rule', '"One owner, one Hub measure, and no leader asked to exceed 6 hours a week."'::jsonb, 'wave205 migration');
  insert into public.strategy_plan (key, value, updated_by) values ('roadmap', '{"title": "Three years to prove it, then grow through the FY29 gate", "phases": [{"key": "FY27", "name": "Stabilize", "dates": "Oct 2026 to Sep 2027", "items": ["Count every meal", "Write every role", "Donor team launched"]}, {"key": "FY28", "name": "Strengthen", "dates": "Oct 2027 to Sep 2028", "items": ["First paid role", "3-month reserve", "Toronto monthly"]}, {"key": "FY29", "name": "Scale", "dates": "Oct 2028 to Sep 2029", "items": ["4,000 meals", "$60,000 revenue", "Two paid roles"]}, {"key": "FY30 to FY31", "name": "Grow", "dates": "Oct 2029 to Sep 2031", "items": ["Weekly Montreal", "Paid program lead", "New city decision"], "gated": true}], "checkpoint": {"name": "Checkpoint, Oct 2027", "after": "FY27", "items": ["Meals counted at every service", "Executive transition complete", "First grant awarded"]}, "gate": {"name": "FY29 gate, Oct 2029", "after": "FY29", "items": ["Reserve held for 12 months", "35% volunteer return", "26 Montreal services delivered", "Toronto self-led"]}, "gate_rule": "FY30 and FY31 targets apply only if all four gate criteria are met in October 2029; otherwise FY29 targets carry forward."}'::jsonb, 'wave205 migration');
  insert into public.strategy_plan (key, value, updated_by) values ('cadence', '["Quarterly board meetings (Jan, Apr, Jul, Oct): a one-page scorecard, one line per goal.", "Every board meeting: the standing strategy block (board item 18).", "Each October: a year-end strategy session (board item 13) that resets next year''s milestones."]'::jsonb, 'wave205 migration');
  insert into public.strategy_plan (key, value, updated_by) values ('source', '{"title": "29/09/26 - Welfare Avenue Organizational Goals FY27 to FY31 (Draft)", "url": "https://claude.ai/code/artifact/4aa082da-baca-48da-935f-245ecc7e5a70"}'::jsonb, 'wave205 migration');
  insert into public.strategy_docs (title, url, group_label, doc_date, direction, status_note, goals, pinned, sort, added_by) values ('Leadership strategic planning 2025-2026', 'https://docs.google.com/spreadsheets/d/1a1QFjiiKBlXijbgg03JcJScBdtAV1g5kMyOR3aNPf4k', 'Our plans', 'Oct 2025', '10-year: $5M revenue, 1M meals; 3-year picture: own kitchen and location, 10 donors over $50K, paid staff', 'FY26 target of $100,000 vs about $13,000 actual', '{}', true, 10, 'wave205 migration');
